/**
 * THE TRIAL REPORTS: one record per landmark lymphoma trial publication, holding the paper's own metadata and
 * the figures from its indexed abstract. Facet C of the lymphoma deep dive.
 *
 * Every record was resolved on Europe PMC by DOI or title on 1 October 2026 and carries that record's title,
 * author string, journal, year, DOI and PubMed id. The trial record in ./lymphoma-evidence-trials.ts carries the
 * registry metadata and the structured outcomes; this file carries the publication.
 *
 * Four of these papers report trials the corpus holds only under a registry-generated id (ELM-2, ECHELON-3,
 * inMIND and ECHO). The paper record is what gives those studies a readable page until the trial records are
 * merged; see REGISTRY_ID_TRIALS in ./lymphoma-evidence-shared.ts.
 */
type P = Omit<PaperInput, "kind" | "asOf">;
const p = (x: P): PaperInput => ({ kind: "paper", asOf, tags: ["lymphoma-evidence"], ...x });

